arguments.command:
cd /workspace && python3 - <<'PYEOF'
import json, resource, subprocess, sys, time

topo = {"nodes": [{"id": i, "name": "N%d" % i, "external_capacity": 100}
                  for i in range(40)],
        "links": [{"source": i, "target": (i + 1) % 40, "capacity": 100} for i in range(40)],
        "external_nodes": ["N%d" % i for i in range(4)]}
settings = {"trials": 8, "epsilon": 100000, "seed": 3, "cutoff": [1, 2], "bias": 0,
            "tau": 500000, "gamma": [4, 5], "cache_slots": 4}


def build(kind):
    if kind == "objects":
        # 8 MiB of tiny annotation objects
        blob = [{"a": i} for i in range(140000)]
        counters = {"low_N0_egress_to_N1": {"perturbed": 1, "ground_truth": blob}}
    elif kind == "empty":
        counters = {"low_N0_egress_to_N1": {"perturbed": 1,
                                           "ground_truth": [{} for _ in range(200000)]}}
    else:
        counters = {"low_N0_egress_to_N1": {"perturbed": 1,
                                           "ground_truth": "x" * 6000000}}
    events = [{"op": "patch", "demands": [[0, 1, 5]], "counters": counters},
              {"op": "routes", "label": "l", "paths": None},
              {"op": "repair", "id": "s"},
              {"op": "validate", "id": "s"}]
    return json.dumps({"streams": [{"topology": topo, "settings": settings,
                                    "events": events}]}, separators=(",", ":"))


for kind in ("objects", "empty", "string"):
    blob = build(kind).encode()
    print(kind, "request MiB %.2f" % (len(blob) / 2 ** 20))
    with open('/workspace/tmp/scratch/fat.json', 'wb') as handle:
        handle.write(blob)
    start = time.time()
    proc = subprocess.run([sys.executable, '-B', '-u', '/workspace/submission/main.py'],
                          stdin=open('/workspace/tmp/scratch/fat.json', 'rb'),
                          capture_output=True, cwd='/workspace/tmp/scratch',
                          env={'PATH': '/usr/local/bin:/usr/bin:/bin',
                               'PYTHONPATH': '/workspace/submission'})
    rss = resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss
    print("  rc", proc.returncode, "elapsed %.2fs" % (time.time() - start),
          "peak RSS %.0f MiB" % (rss / 1024.0), "out", len(proc.stdout),
          proc.stderr.decode()[:120])
PYEOF
